fn github_release_package_not_release_eligible_never_errors() {
    use callisto_graph::commands::{plan_publish, PublishOptions};

    let runner = DummyRunner;
    let ws_dir = tempfile::tempdir().unwrap();
    let root = ws_dir.path();
    std::fs::write(
        root.join("Cargo.toml"),
        "[package]\nname = \"my-crate\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
    )
    .unwrap();
    std::fs::write(
        root.join("callisto.toml"),
        "[[package]]\nmatch = \"my-crate\"\npublish-to = [\"github-release\"]\n",
    )
    .unwrap();
    init_git_repo(root);
    let status = std::process::Command::new("git")
        .args(["tag", "my-crate@1.0.0"])
        .current_dir(root)
        .status()
        .unwrap();
    assert!(status.success());

    let locator = callisto_graph::locate::IgnoreWalkLocator::new(root);
    let ws = callisto_graph::Workspace::load(root.to_path_buf(), &locator, &runner).unwrap();

    let plan = plan_publish(&ws, &PublishOptions::default())
        .expect("AC-009: not-release-eligible package must never hit MissingGitHubReleaseAssets even with zero configured assets");
    let pkg_id = PackageId::parse("my-crate").unwrap();
    assert!(plan.releases.iter().all(|r| r.package != pkg_id), "no ReleaseEntry expected for a non-release-eligible package");
}

