#[test]
fn github_release_package_with_no_assets_configured_hard_errors() {
    use callisto_graph::commands::{plan_publish, PublishOptions};
    use callisto_model::{ManifestDecl, ManifestFormat, ManifestRole};

    let runner = DummyRunner;
    let ws_dir = tempfile::tempdir().unwrap();
    let root = ws_dir.path();

    std::fs::write(
        root.join("Cargo.toml"),
        "[package]\nname = \"my-crate\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
    )
    .unwrap();
    init_git_repo(root);

    let pkg_id = PackageId::parse("my-crate").unwrap();
    let cargo_decl = ManifestDecl::new(
        PathBuf::from("Cargo.toml"),
        ManifestRole::Canonical,
        ManifestFormat::CargoToml,
    )
    .unwrap();

    let graph = GraphBuilder::new()
        .package(pkg_id.clone(), |p: PackageBuilder| {
            p.manifests(vec![cargo_decl]).publish_to(vec![PublishTarget::GitHubRelease])
        })
        .build()
        .unwrap();

    let cfg = callisto_graph::config::load(root).unwrap();
    let ws = callisto_graph::Workspace {
        root: root.to_path_buf(),
        config: cfg,
        graph,
        tags: OnceCell::new(),
        git: OnceCell::new(),
        runner: &runner,
        manifest_cache: Default::default(),
        identity: callisto_graph::IdentityIndex::default(),
    };

    let result = plan_publish(&ws, &PublishOptions::default());
    assert!(
        matches!(result, Err(callisto_graph::GraphError::MissingGitHubReleaseAssets { ref package }) if *package == pkg_id),
        "expected MissingGitHubReleaseAssets naming my-crate; got: {result:?}"
    );
}

