#[test]
fn github_release_package_with_assets_gets_populated_release_entry_no_diagnostic() {
    use callisto_graph::commands::{plan_publish, PublishOptions};
    use callisto_model::{DiagnosticCode, GitHubReleaseAsset, ManifestDecl, ManifestFormat, ManifestRole};

    let runner = DummyRunner;
    let ws_dir = tempfile::tempdir().unwrap();
    let root = ws_dir.path();
    std::fs::write(
        root.join("Cargo.toml"),
        "[package]\nname = \"my-crate\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
    )
    .unwrap();
    init_git_repo(root);

    let pkg_id = PackageId::parse("my-crate").unwrap();
    let cargo_decl = ManifestDecl::new(PathBuf::from("Cargo.toml"), ManifestRole::Canonical, ManifestFormat::CargoToml).unwrap();
    let assets = vec![
        GitHubReleaseAsset { triple: "x86_64-unknown-linux-gnu".into(), artifact_path: PathBuf::from("dist/a-linux"), asset_name: "a-linux".into() },
        GitHubReleaseAsset { triple: "aarch64-apple-darwin".into(), artifact_path: PathBuf::from("dist/a-mac"), asset_name: "a-mac".into() },
        GitHubReleaseAsset { triple: "x86_64-pc-windows-msvc".into(), artifact_path: PathBuf::from("dist/a-win.exe"), asset_name: "a-win".into() },
    ];

    let graph = GraphBuilder::new()
        .package(pkg_id.clone(), |p: PackageBuilder| {
            p.manifests(vec![cargo_decl])
                .publish_to(vec![PublishTarget::GitHubRelease])
                .github_release_assets(assets.clone())
        })
        .build()
        .unwrap();

    let cfg = callisto_graph::config::load(root).unwrap();
    let ws = callisto_graph::Workspace {
        root: root.to_path_buf(),
        config: cfg,
        graph,
        tags: OnceCell::new(),
        git: OnceCell::new(),
        runner: &runner,
        manifest_cache: Default::default(),
        identity: callisto_graph::IdentityIndex::default(),
    };

    let plan = plan_publish(&ws, &PublishOptions::default()).expect("plan_publish must succeed once assets are configured");

    assert!(
        !plan.diagnostics.iter().any(|d| d.code == DiagnosticCode::PublishTargetNotImplemented && d.package.as_ref() == Some(&pkg_id)),
        "AC-003: no PublishTargetNotImplemented diagnostic expected; got: {:?}", plan.diagnostics
    );
    let entry = plan.releases.iter().find(|r| r.package == pkg_id).expect("AC-004: ReleaseEntry must be present");
    assert_eq!(entry.assets, assets, "AC-005: assets must match config order exactly, no re-sorting");
    assert!(!entry.tag_name.as_str().is_empty());
    assert!(!entry.sha.as_str().is_empty());
}

